definition.script:
def retrieveBuildSpecId;
def pipelineBuildId;
def migrationBuildNumber;
pipeline {
    agent any
    stages {
        stage('Set Project Up') {
            steps {
                script {
                    sh """
                        sed -i "s|__RELEASE_CONTROL_REPO__|$env.RELEASE_CONTROL_REPOSITORY|g" /var/jenkins_home/config.xml
                        sed -i "s|__PROJECT_SPECIFIC_MIGRATION_NAME__|$env.PROJECT_MIGRATION_NAME|g" /var/jenkins_home/config.xml
                    """
                    Jenkins.instance.doReload()
                }

                script {
                    def result = build job: 'Retrieve Build Spec'
                    retrieveBuildSpecId = result.number
                }

                script {
                    copyArtifacts filter: '*', projectName: 'Retrieve Build Spec', selector: specific(""+retrieveBuildSpecId)
                    sh 'cat build-spec.json'
                    sh 'cat pipeline_git_commit.txt'
                    sh 'pwd'
                    pipelineBuildId = new File('/var/jenkins_home/workspace/Initial Configuration Pipeline/pipeline_git_commit.txt').text.trim()
                }
            }
        }

        stage('Confirm Authenticated HPDS Is Public') {
            when {
                expression { env.ENABLE_EXPLORE_WITHOUT_LOGIN.toBoolean() && !env.CONFIRM_AUTH_HPDS_PUBLIC.toBoolean() }
            }
            steps {
                error('CONFIRM_AUTH_HPDS_PUBLIC must be true when ENABLE_EXPLORE_WITHOUT_LOGIN=true.')
            }
        }

        stage('Write and Validate Configuration') {
            steps {
                script {
                    sh "[ ! -f /usr/local/docker-config/httpd/httpd.env ] || cp -rf /usr/local/docker-config/httpd/httpd.env /usr/local/docker-config/httpd/httpd.env.bak"
                    sh "install -m 664 /dev/null .env"
                    sh "echo 'VITE_PROJECT_HOSTNAME=' >> .env"
                    sh "echo 'VITE_ORIGIN=' >> .env"
                    sh "echo 'VITE_LOGO=' >> .env"
                    sh "echo 'VITE_AUTH0_TENANT=$env.AUTH0_TENANT' >> .env"
                    sh "echo 'VITE_DISCOVER=$env.ENABLE_OPEN_ACCESS' >> .env"
                    sh "echo 'VITE_DASHBOARD=$env.DASHBOARD' >> .env"
                    sh "echo 'VITE_DIST_EXPLORER=$env.DIST_EXPLORER' >> .env"
                    sh "echo 'VITE_API=$env.API' >> .env"
                    sh "echo 'VITE_ALLOW_EXPORT=$env.ALLOW_EXPORT' >> .env"
                    sh "echo 'VITE_ALLOW_EXPORT_ENABLED=$env.VITE_ALLOW_EXPORT_ENABLED' >> .env"
                    sh "echo 'VITE_DOWNLOAD_AS_CSV=$env.DOWNLOAD_AS_CSV' >> .env"
                    sh "echo 'VITE_SHOW_VARIABLE_EXPORT=$env.SHOW_VARIABLE_EXPORT' >> .env"
                    sh "echo 'VITE_SHOW_VARIABLE_HIERARCHY=$env.SHOW_VARIABLE_HIERARCHY' >> .env"
                    sh "echo 'VITE_DOWNLOAD_AS_PFB=$env.DOWNLOAD_AS_PFB' >> .env"
                    sh "echo 'VITE_DATA_REQUESTS=$env.DATA_REQUESTS' >> .env"
                    sh "echo 'VITE_TOUR=$env.TOUR' >> .env"
                    sh "echo 'VITE_TOUR_SEARCH_TERM=$env.TOUR_SEARCH_TERM' >> .env"
                    sh "echo 'VITE_REQUIRE_CONSENTS=false' >> .env"
                    sh "echo 'VITE_USE_QUERY_TEMPLATE=false' >> .env"
                    sh "echo 'VITE_ENABLE_TOS=true' >> .env"
                    sh "echo '#Login Provider (You may add as many as you would like):' >> .env"
                    sh "echo 'VITE_AUTH_PROVIDER_MODULE_GOOGLE=true' >> .env"
                    sh "echo 'VITE_AUTH_PROVIDER_MODULE_GOOGLE_TYPE=AUTH0' >> .env"
                    sh "echo 'VITE_AUTH_PROVIDER_MODULE_GOOGLE_CLIENTID=$env.AUTH0_CLIENT_ID' >> .env"
                    sh "echo 'VITE_AUTH_PROVIDER_MODULE_GOOGLE_CONNECTION=google-oauth2' >> .env"
                    sh "echo 'VITE_AUTH_PROVIDER_MODULE_GOOGLE_DESCRIPTION=Login' >> .env"
                    sh "echo '#Google Analytics settings (leave blank to disable):' >> .env"
                    sh "echo 'VITE_GOOGLE_ANALYTICS_ID=' >> .env"
                    sh "echo 'VITE_GOOGLE_TAG_MANAGER_ID=' >> .env"
                    sh "mv .env '/usr/local/docker-config/httpd/httpd.env'"

                    def result = build job: 'Enable Explore Without Login', parameters: [
                        [$class: 'BooleanParameterValue', name: 'ENABLE_EXPLORE_WITHOUT_LOGIN', value: env.ENABLE_EXPLORE_WITHOUT_LOGIN.toBoolean()],
                        [$class: 'BooleanParameterValue', name: 'CONFIRM_AUTH_HPDS_PUBLIC', value: env.CONFIRM_AUTH_HPDS_PUBLIC.toBoolean()]
                    ]
                }
            }
        }

        stage('Initial Service Configuration') {
            steps {
                parallel (
                    auth0Config: {
                        script {
                            def result = build job: 'Configure Auth0 Integration', parameters: [
                                [$class: 'StringParameterValue', name: 'AUTH0_CLIENT_ID', value:env.AUTH0_CLIENT_ID],
                                [$class: 'StringParameterValue', name: 'AUTH0_CLIENT_SECRET', value: env.AUTH0_CLIENT_SECRET],
                                [$class: 'StringParameterValue', name: 'AUTH0_TENANT', value: env.AUTH0_TENANT]
                            ]
                        }
                    },
                    addRootCerts: {
                        script {
                            catchError(buildResult: 'SUCCESS', stageResult: 'UNSTABLE') {
                                def result = build job: 'Create Root Certs in TrustStore'
                            }
                        }
                    }
                )
            }
        }

        stage('Migrations') {
            steps {
                script {
                    def result = build job: 'PIC-SURE Database Migrations', parameters: [
                        [$class: 'StringParameterValue', name: 'release_control_commit', value: pipelineBuildId]
                    ]
                    migrationBuildNumber = result.number
                }
            }
        }

        stage('Application Build') {
            steps {
                script {
                    def result = build job: 'PIC-SURE Pipeline', parameters: [
                        [$class: 'StringParameterValue', name: 'release_control_commit', value: pipelineBuildId],
                        [$class: 'StringParameterValue', name: 'migration_build_number', value: "" + migrationBuildNumber]
                    ]
                }
            }
        }

        stage('Post Migration Configs') {
            steps {
                parallel (
                    adminConfig: {
                        script {
                            def result = build job: 'Create Admin User', parameters: [
                                [$class: 'StringParameterValue', name: 'EMAIL', value:env.ADMIN_USER_EMAIL],
                                [$class: 'StringParameterValue', name: 'CONNECTION_LABEL', value: "Google"]
                            ]
                        }
                    },
                    tokenIntroToken: {
                        script {
                            def result = build job: 'Configure PIC-SURE Token Introspection Token'
                        }
                    },
                    encryptionKey: {
                        script {
                            def result = build job: 'Create HPDS Encryption Key'
                        }
                    }
                )
            }
        }


        stage('Apply Configuration') {
            steps {
                script {
                    // The gateway came up in Application Build with the token
                    // placeholder; Post Migration Configs only wrote the real one to
                    // gateway.env. Recreate the stack now rather than leaving it stale
                    // for the whole demo-data load.
                    def result = build job: 'Start PIC-SURE', parameters: [[$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]]
                }
            }
        }

        stage('Load Demo Data') {
            steps {
                script {
                    def result = build job: 'Load HPDS and Dictionary Data', parameters: [
                        [$class: 'StringParameterValue', name: 'Dataset', value: env.Dataset],
                        [$class: 'StringParameterValue', name: 'Dataset_Branch', value: env.Dataset_Branch],
                        [$class: 'BooleanParameterValue', name: 'Allow_HPDS_Data_Export', value: env.Allow_HPDS_Data_Export],
                        [$class: 'BooleanParameterValue', name: 'Clear_Dictionary_Database', value: true],
                        [$class: 'BooleanParameterValue', name: 'Include_Dataset_Facets', value: env.Include_Dataset_Facets]
                    ]
                }
            }
        }

        stage('Deploy') {
            steps {
                script {
                    def result = build job: 'Start PIC-SURE', parameters: [[$class: 'StringParameterValue', name: 'pipeline_build_id', value: pipelineBuildId]]
                }
            }
        }
    }
}
